//! # AST 模块
//!
//! 定义脚本的抽象语法树（Abstract Syntax Tree）。
//!
//! ## 设计说明
//!
//! AST 是解析器的输出，表示脚本的结构化表示。
//! 执行引擎读取 AST 并产生 Command。

use serde::{Deserialize, Serialize};

use crate::{
    command::{InlineEffect, Position, TextMode, Transition},
    script::Expr,
};

/// 选择项（AST 级别）
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChoiceOption {
    /// 选项显示文本
    pub text: String,
    /// 跳转目标标签
    pub target_label: String,
}

/// 条件分支
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ConditionalBranch {
    /// 条件表达式（None 表示 else 分支）
    pub condition: Option<Expr>,
    /// 分支内的节点列表
    pub body: Vec<ScriptNode>,
}

/// 脚本节点
///
/// 表示脚本中的一个执行单元。
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum ScriptNode {
    /// 章节标记
    ///
    /// 对应 Markdown 标题语法 `# Chapter 1`
    Chapter {
        /// 章节标题
        title: String,
        /// 章节级别（1-6）
        level: u8,
    },

    /// 标签定义
    ///
    /// 对应 `**label_name**` 语法
    Label {
        /// 标签名
        name: String,
    },

    /// 对话
    ///
    /// 对应 `角色名："对话内容"` 语法。
    /// 支持内联节奏标签（`{wait}`, `{speed}` 等）和行尾 `-->` 自动推进。
    Dialogue {
        /// 说话者名称（None 表示旁白）
        speaker: Option<String>,
        /// 对话内容（纯文本，标签已剥离）
        content: String,
        /// 内联效果列表（位置索引到纯文本字符位置）
        inline_effects: Vec<InlineEffect>,
        /// 是否自动推进（来自行尾 `-->` 修饰符）
        no_wait: bool,
    },

    /// 台词续接（不清屏追加文本）
    ///
    /// 对应 `extend "追加文本"` 语法。
    /// 继承上一行的 speaker，打字机从当前位置继续。
    Extend {
        /// 追加文本（纯文本，标签已剥离）
        content: String,
