在 `tests.rs` 底部新增：
```rust
#[test]
fn test_extract_quoted_path() {
    use super::helpers::extract_quoted_path;

    assert_eq!(extract_quoted_path(r#""bg/sunset.png""#), Some("bg/sunset.png"));
    assert_eq!(extract_quoted_path(r#"changeBG "bg/sunset.png" with dissolve"#), Some("bg/sunset.png"));
    assert_eq!(extract_quoted_path(r#"show "characters/alice.png" as alice at left"#), Some("characters/alice.png"));
    assert_eq!(extract_quoted_path(r#"bgm "../audio/BGM/theme.mp3""#), Some("../audio/BGM/theme.mp3"));
