```rust
/// 从字符串中提取第一个双引号包裹的路径
///
/// 输入: `changeBG "path/to/bg.png" with dissolve`
/// 输出: `Some("path/to/bg.png")`
pub fn extract_quoted_path(s: &str) -> Option<&str> {
    let start = s.find('"')?;
    let after_quote = &s[start + 1..];
    let end = after_quote.find('"')?;
    Some(&after_quote[..end])
}
```

