```rust
/// 检测并剥离行尾修饰符：`-->` (no_wait) 和 `notend` (not_end)
fn strip_line_suffixes(line: &str) -> (&str, bool, bool) {
    let trimmed = line.trim_end();

    // 先检查 notend
    if let Some(before) = trimmed.strip_suffix("notend") {
        let before = before.trim_end();
        return (before, false, true);
    }

    // 再检查 -->
    if let Some(before) = trimmed.strip_suffix("-->") {
        return (before, true, false);
    }

    (line, false, false)
}
```

