```rust
/// 解析 bgm 指令
///
/// 语法: `bgm "path/to/audio.mp3"`
pub(super) fn parse_bgm(
    &self,
    line: &str,
    line_number: usize,
) -> Result<Option<ScriptNode>, ParseError> {
    let content = line.get(3..).map(str::trim).filter(|s| !s.is_empty());
    let path = content
        .and_then(extract_quoted_path)
        .ok_or_else(|| ParseError::MissingParameter {
            line: line_number,
            command: "bgm".to_string(),
            param: "音频路径 (\"path\")".to_string(),
        })?;

    Ok(Some(ScriptNode::PlayAudio {
        path: path.to_string(),
        is_bgm: true,
    }))
}

/// 解析 sfx 指令
///
/// 语法: `sfx "path/to/audio.mp3"`
pub(super) fn parse_sfx(
    &self,
    line: &str,
    line_number: usize,
) -> Result<Option<ScriptNode>, ParseError> {
    let content = line.get(3..).map(str::trim).filter(|s| !s.is_empty());
    let path = content
        .and_then(extract_quoted_path)
        .ok_or_else(|| ParseError::MissingParameter {
            line: line_number,
            command: "sfx".to_string(),
            param: "音频路径 (\"path\")".to_string(),
        })?;

    Ok(Some(ScriptNode::PlayAudio {
        path: path.to_string(),
        is_bgm: false,
    }))
}
```

