201	    pub(in crate::script::parser) fn extract_transition_from_line(
202	        &self,
203	        line: &str,
204	    ) -> Option<Transition> {
205	        let lower = line.to_lowercase();
206	
207	        let with_pos = lower
208	            .rfind(" with ")
209	            .or_else(|| lower.rfind(">with "))
210	            .or_else(|| lower.rfind(" with`"))
211	            .or_else(|| lower.rfind(">with`"))?;
212	
213	        let with_slice = &lower[with_pos..];
214	        let text_after_with =
215	            if with_slice.starts_with(" with ") || with_slice.starts_with(">with ") {
216	                &line[with_pos + 6..]
217	            } else {
218	                &line[with_pos + 5..]
219	            };
220	
221	        let transition_text = text_after_with.trim();
222	
223	        if transition_text.contains("<img") {
224	            if let Some(rule_path) = extract_img_src(transition_text) {
225	                let args = self.extract_rule_args(transition_text, rule_path);
226	                return Some(Transition::with_named_args("rule", args));
227	            }
228	            return Some(Transition::simple("rule"));
229	        }
230	
231	        let transition_text = if let Some(stripped) = transition_text.strip_prefix('`') {
232	            if let Some(stripped) = stripped.strip_suffix('`') {
233	                stripped
234	            } else if let Some(end) = stripped.find('`') {
235	                &stripped[..end]
236	            } else {
237	                stripped
238	            }
239	        } else {
240	            transition_text
241	        };
242	
243	        parse_transition(transition_text.trim())
244	    }
245	
246	    /// 从 rule-based effect 文本中提取参数
247	    fn extract_rule_args(
248	        &self,
249	        text: &str,
250	        mask_path: &str,
251	    ) -> Vec<(Option<String>, TransitionArg)> {
252	        let mut args = vec![(
253	            Some("mask".to_string()),
254	            TransitionArg::String(mask_path.to_string()),
255	        )];
256	
257	        if let Some(img_end) = text.find("/>") {
258	            let after_img = &text[img_end + 2..];
259	            if let Some(paren_start) = after_img.find('(')
260	                && let Some(paren_end) = after_img.rfind(')')
261	            {
262	                let params_str = &after_img[paren_start + 1..paren_end];
263	                if let Ok(parsed_args) = parse_transition_args(params_str) {
264	                    args.extend(parsed_args);
265	                }
266	            }
267	        }
268	
269	        args
270	    }
271	}
