```rust
use tower_lsp::lsp_types::*;
use vn_runtime::diagnostic as vn_diag;
use vn_runtime::script::parser::Parser;

use crate::state::DocumentState;

pub fn analyze_document(doc: &mut DocumentState, uri: &Url) {
    let script_id = uri.path();
    let mut parser = Parser::new();

    match parser.parse(script_id, &doc.content) {
        Ok(script) => {
            let vn_result = vn_diag::analyze_script(&script);
            doc.diagnostics = vn_result
                .diagnostics
                .iter()
                .map(|d| to_lsp_diagnostic(d))
                .collect();
            doc.script = Some(script);
        }
        Err(parse_err) => {
            doc.diagnostics = vec![parse_error_to_diagnostic(&parse_err)];
            doc.script = None;
        }
    }
}

fn to_lsp_diagnostic(d: &vn_diag::Diagnostic) -> Diagnostic {
    let line = d.line.unwrap_or(1).saturating_sub(1) as u32;
    Diagnostic {
        range: Range::new(Position::new(line, 0), Position::new(line, u32::MAX)),
        severity: Some(match d.level {
            vn_diag::DiagnosticLevel::Error => DiagnosticSeverity::ERROR,
            vn_diag::DiagnosticLevel::Warn => DiagnosticSeverity::WARNING,
            vn_diag::DiagnosticLevel::Info => DiagnosticSeverity::INFORMATION,
        }),
        source: Some("ring-lsp".to_string()),
        message: d.message.clone(),
        ..Default::default()
    }
}

fn parse_error_to_diagnostic(err: &vn_runtime::error::ParseError) -> Diagnostic {
    let (line, message) = match err {
        vn_runtime::error::ParseError::InvalidLine { line, message } => (*line, message.clone()),
        vn_runtime::error::ParseError::MissingParameter { line, command, param } => {
            (*line, format!("{command}: 缺少参数 {param}"))
        }
        vn_runtime::error::ParseError::InvalidParameter { line, param, message } => {
            (*line, format!("参数 {param} 无效: {message}"))
        }
        vn_runtime::error::ParseError::InvalidTransition { line, message } => {
            (*line, message.clone())
        }
    };
    let line_0 = line.saturating_sub(1) as u32;
    Diagnostic {
        range: Range::new(Position::new(line_0, 0), Position::new(line_0, u32::MAX)),
        severity: Some(DiagnosticSeverity::ERROR),
        source: Some("ring-lsp".to_string()),
        message,
        ..Default::default()
    }
}
```

