fn find_after_keyword<'a>(text: &'a str, keyword: &str) -> Option<&'a str> {
    let lower = text.to_lowercase();
    let pattern = format!(" {keyword} ");
    if let Some(pos) = lower.rfind(&pattern) {
        Some(&text[pos + pattern.len()..])
    } else {
        None
    }
