use tower_lsp::lsp_types::*;
use vn_runtime::script::ast::{Script, ScriptNode};
use crate::state::{ServerState, DocumentState};

pub fn goto_definition(state: &ServerState, params: &GotoDefinitionParams) -> Option<GotoDefinitionResponse> {
    let uri = &params.text_document_position_params.text_document.uri;
    let pos = params.text_document_position_params.position;
    let doc = state.documents.get(uri)?;
    let line_text = get_line_text(&doc.content, pos.line);

    // goto <label> → jump to * <label> definition
    if let Some(target) = extract_goto_target(line_text) {
        return find_label_definition(doc, uri, &target);
    }

    // callScript "path" → jump to file
    if let Some(path) = extract_call_script_path(line_text) {
        return resolve_script_path(state, uri, &path);
    }

    None
}

fn find_label_definition(doc: &DocumentState, uri: &Url, target: &str) -> Option<GotoDefinitionResponse> {
    let script = doc.script.as_ref()?;
    let label_idx = script.find_label(target)?;
    let line = script.get_source_line(label_idx)?.saturating_sub(1) as u32;
    Some(GotoDefinitionResponse::Scalar(Location {
        uri: uri.clone(),
        range: Range::new(Position::new(line, 0), Position::new(line, 0)),
    }))
}

fn resolve_script_path(state: &ServerState, current_uri: &Url, path: &str) -> Option<GotoDefinitionResponse> {
    let root = state.workspace_root.as_ref()?;
    // Resolve relative to current script's directory
    let current_path = std::path::Path::new(current_uri.path());
    let dir = current_path.parent()?;
    let target = dir.join(path);
    let target_uri = Url::from_file_path(&target).ok()?;
    Some(GotoDefinitionResponse::Scalar(Location {
        uri: target_uri,
        range: Range::new(Position::new(0, 0), Position::new(0, 0)),
    }))
}

fn extract_goto_target(line: &str) -> Option<String> {
    let trimmed = line.trim();
    if trimmed.to_lowercase().starts_with("goto ") {
        Some(trimmed[5..].trim().to_string())
    } else {
        None
    }
}

fn extract_call_script_path(line: &str) -> Option<String> {
    let trimmed = line.trim();
    if trimmed.to_lowercase().starts_with("callscript ") {
        let after = &trimmed["callscript ".len()..].trim();
        // Extract quoted path
        let start = after.find('"')?;
        let rest = &after[start + 1..];
        let end = rest.find('"')?;
        Some(rest[..end].to_string())
    } else {
        None
    }
}

fn get_line_text(content: &str, line: u32) -> &str {
    content.lines().nth(line as usize).unwrap_or("")
}
