```rust
use tower_lsp::lsp_types::*;
use crate::builtins::{COMMANDS, TRANSITIONS, POSITIONS, SCENE_EFFECTS};
use crate::state::ServerState;

pub fn complete(state: &ServerState, params: &CompletionParams) -> Vec<CompletionItem> {
    let uri = &params.text_document_position.text_document.uri;
    let pos = params.text_document_position.position;

    let Some(doc) = state.documents.get(uri) else {
        return Vec::new();
    };

    let line_text = get_line_text(&doc.content, pos.line);
    let prefix = &line_text[..pos.character as usize].trim_start();

    // 行首空内容 → 指令补全
    if prefix.is_empty() {
        return command_completions();
    }

    // "with " 后面 → 过渡效果补全
    if let Some(after_with) = find_after_keyword(prefix, "with") {
        return transition_completions(after_with);
    }

    // "at " 后面 → 位置补全
    if let Some(after_at) = find_after_keyword(prefix, "at") {
        return position_completions(after_at);
    }

    // "sceneEffect " 后面 → 场景效果补全
    if prefix.to_lowercase().starts_with("sceneeffect ") {
        return scene_effect_completions();
    }

    // "goto " 后面 → 标签补全
    if prefix.to_lowercase().starts_with("goto ") {
        return label_completions(doc);
    }

    // 部分输入的指令名 → 过滤指令补全
    if !prefix.contains(' ') && !prefix.contains('"') {
        return filtered_command_completions(prefix);
    }

    Vec::new()
}

fn command_completions() -> Vec<CompletionItem> {
    COMMANDS.iter().map(|cmd| CompletionItem {
        label: cmd.name.to_string(),
        kind: Some(CompletionItemKind::KEYWORD),
        detail: Some(cmd.syntax.to_string()),
        documentation: Some(Documentation::String(cmd.description.to_string())),
        ..Default::default()
    }).collect()
}

fn filtered_command_completions(prefix: &str) -> Vec<CompletionItem> {
    COMMANDS.iter()
        .filter(|cmd| cmd.name.to_lowercase().starts_with(&prefix.to_lowercase()))
        .map(|cmd| CompletionItem {
            label: cmd.name.to_string(),
            kind: Some(CompletionItemKind::KEYWORD),
            detail: Some(cmd.syntax.to_string()),
            ..Default::default()
        })
        .collect()
}

fn transition_completions(_prefix: &str) -> Vec<CompletionItem> {
    TRANSITIONS.iter().map(|t| CompletionItem {
        label: t.to_string(),
        kind: Some(CompletionItemKind::ENUM_MEMBER),
        ..Default::default()
    }).collect()
}

fn position_completions(_prefix: &str) -> Vec<CompletionItem> {
    POSITIONS.iter().map(|p| CompletionItem {
        label: p.to_string(),
        kind: Some(CompletionItemKind::ENUM_MEMBER),
        ..Default::default()
    }).collect()
}

fn scene_effect_completions() -> Vec<CompletionItem> {
    SCENE_EFFECTS.iter().map(|e| CompletionItem {
        label: e.to_string(),
        kind: Some(CompletionItemKind::ENUM_MEMBER),
        ..Default::default()
    }).collect()
}

fn label_completions(doc: &crate::state::DocumentState) -> Vec<CompletionItem> {
    let Some(script) = &doc.script else { return Vec::new() };
    vn_runtime::diagnostic::get_defined_labels(script)
        .into_iter()
        .map(|label| CompletionItem {
            label: label.to_string(),
            kind: Some(CompletionItemKind::REFERENCE),
            ..Default::default()
        })
        .collect()
}

fn get_line_text(content: &str, line: u32) -> &str {
    content.lines().nth(line as usize).unwrap_or("")
}

fn find_after_keyword<'a>(text: &'a str, keyword: &str) -> Option<&'a str> {
    let lower = text.to_lowercase();
    let pattern = format!(" {keyword} ");
    if let Some(pos) = lower.rfind(&pattern) {
        Some(&text[pos + pattern.len()..])
    } else {
        None
    }
}
```

