```rust
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AssetType {
    Image,
    Audio,
    Video,
    Script,
    Other,
}

#[derive(Debug, Clone)]
pub struct AssetEntry {
    pub absolute_path: PathBuf,
    pub relative_path: String,
    pub asset_type: AssetType,
}

#[derive(Debug, Default)]
pub struct AssetIndex {
    entries: BTreeMap<String, AssetEntry>,
}

impl AssetIndex {
    pub fn scan(assets_dir: &Path) -> Self {
        let mut index = Self::default();
        if !assets_dir.exists() {
            return index;
        }

        for entry in WalkDir::new(assets_dir).into_iter().filter_map(|e| e.ok()) {
            if !entry.file_type().is_file() {
                continue;
            }
            let abs_path = entry.path().to_path_buf();
            let rel_path = entry.path()
                .strip_prefix(assets_dir)
                .unwrap_or(entry.path())
                .to_string_lossy()
                .replace('\\', "/");

            let asset_type = classify_extension(&abs_path);
            index.entries.insert(rel_path.clone(), AssetEntry {
                absolute_path: abs_path,
                relative_path: rel_path,
                asset_type,
            });
        }
        index
    }

    pub fn completions_for_type(&self, asset_type: &AssetType, prefix: &str) -> Vec<&AssetEntry> {
        self.entries.values()
            .filter(|e| &e.asset_type == asset_type || asset_type == &AssetType::Other)
            .filter(|e| e.relative_path.contains(prefix) || prefix.is_empty())
            .collect()
    }

    pub fn exists(&self, relative_path: &str) -> bool {
        self.entries.contains_key(relative_path)
    }

    pub fn get(&self, relative_path: &str) -> Option<&AssetEntry> {
        self.entries.get(relative_path)
    }

    pub fn rescan(&mut self, assets_dir: &Path) {
        *self = Self::scan(assets_dir);
    }
}

fn classify_extension(path: &Path) -> AssetType {
    match path.extension().and_then(|e| e.to_str()).unwrap_or("") {
        "png" | "jpg" | "jpeg" | "webp" | "bmp" => AssetType::Image,
        "mp3" | "ogg" | "wav" | "flac" => AssetType::Audio,
        "mp4" | "webm" => AssetType::Video,
        "rks" => AssetType::Script,
        _ => AssetType::Other,
    }
}
```

