```rust
pub fn document_symbols(doc: &DocumentState) -> Vec<DocumentSymbol> {
    let Some(script) = &doc.script else { return Vec::new() };
    let mut symbols = Vec::new();

    for (idx, node) in script.nodes.iter().enumerate() {
        let line = script.get_source_line(idx).unwrap_or(1).saturating_sub(1) as u32;
        let range = Range::new(Position::new(line, 0), Position::new(line, u32::MAX));

        match node {
            ScriptNode::Chapter { title, .. } => {
                symbols.push(DocumentSymbol {
                    name: title.clone(),
                    kind: SymbolKind::NAMESPACE,
                    range,
                    selection_range: range,
                    detail: None,
                    children: None,
                    tags: None,
                    deprecated: None,
                });
            }
            ScriptNode::Label { name } => {
                symbols.push(DocumentSymbol {
                    name: name.clone(),
                    kind: SymbolKind::KEY,
                    range,
                    selection_range: range,
                    detail: Some("label".to_string()),
                    children: None,
                    tags: None,
                    deprecated: None,
                });
            }
            ScriptNode::Choice { options, .. } => {
                let opts: Vec<String> = options.iter().map(|o| o.text.clone()).collect();
                symbols.push(DocumentSymbol {
                    name: format!("choice: {}", opts.join(" / ")),
                    kind: SymbolKind::ENUM,
                    range,
                    selection_range: range,
                    detail: None,
                    children: None,
                    tags: None,
                    deprecated: None,
                });
            }
            _ => {}
        }
    }
    symbols
}
