```rust
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AssetType {
    Image,
    Audio,
    Video,
    Script,
    Other,
}

#[derive(Debug, Clone)]
pub struct AssetEntry {
    pub relative_path: String,
    pub asset_type: AssetType,
}

#[derive(Debug, Default)]
pub struct AssetIndex {
    entries: BTreeMap<String, AssetEntry>,
}

impl AssetIndex {
    pub fn scan(assets_dir: &Path) -> Self {
        let mut index = Self::default();
        if !assets_dir.exists() {
            return index;
        }
        for entry in WalkDir::new(assets_dir).into_iter().filter_map(Result::ok) {
            if !entry.file_type().is_file() {
                continue;
            }
            let rel_path = entry.path()
                .strip_prefix(assets_dir)
                .unwrap_or(entry.path())
                .to_string_lossy()
                .replace('\\', "/");
            let asset_type = classify_extension(entry.path());
            index.entries.insert(rel_path.clone(), AssetEntry {
                relative_path: rel_path,
                asset_type,
            });
        }
        index
    }

    pub fn completions_for_type(&self, filter_type: &AssetType) -> Vec<&AssetEntry> {
        self.entries.values()
            .filter(|e| &e.asset_type == filter_type)
            .collect()
    }

    pub fn all_entries(&self) -> impl Iterator<Item = &AssetEntry> {
        self.entries.values()
    }

    pub fn exists(&self, relative_path: &str) -> bool {
        // 规范化路径分隔符后查找
        let normalized = relative_path.replace('\\', "/");
        self.entries.contains_key(&normalized)
    }
}

fn classify_extension(path: &Path) -> AssetType {
    match path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase().as_str() {
        "png" | "jpg" | "jpeg" | "webp" | "bmp" => AssetType::Image,
        "mp3" | "ogg" | "wav" | "flac" => AssetType::Audio,
        "mp4" | "webm" => AssetType::Video,
        "rks" => AssetType::Script,
        _ => AssetType::Other,
    }
}
```

