2. Goto Definition（跳转到标签定义、callScript 目标文件）
3. Find References（标签的所有引用）
4. Document Symbols（文档大纲：章节/标签/分支）
5. Hover（指令文档、标签定义位置）

## 具体要求

### 1. 变量补全（修改 completion.rs）

在 `complete()` 函数中，在路径检测之后添加变量补全检测：

```rust
// $变量补全
if prefix.contains('$') {
    return variable_completions(doc);
}
```

实现 `variable_completions`，从 AST 中提取所有 `SetVar` 节点的变量名：
```rust
fn variable_completions(doc: &crate::state::DocumentState) -> Vec<CompletionItem> {
    let Some(script) = &doc.script else { return Vec::new() };
    let mut vars: Vec<String> = Vec::new();
    collect_variables(&script.nodes, &mut vars);
    vars.sort();
    vars.dedup();
    vars.into_iter()
        .map(|name| CompletionItem {
            label: format!("${name}"),
            kind: Some(CompletionItemKind::VARIABLE),
            ..Default::default()
        })
        .collect()
}

fn collect_variables(nodes: &[vn_runtime::script::ast::ScriptNode], vars: &mut Vec<String>) {
    use vn_runtime::script::ast::ScriptNode;
    for node in nodes {
        match node {
            ScriptNode::SetVar { name, .. } => vars.push(name.clone()),
            ScriptNode::Conditional { branches } => {
                for branch in branches {
                    collect_variables(&branch.body, vars);
                }
            }
            _ => {}
        }
    }
}
```

### 2. 创建 `tools/ring-lsp/src/navigation.rs`

```rust
use tower_lsp::lsp_types::*;
use vn_runtime::script::ast::ScriptNode;
use crate::state::{ServerState, DocumentState};

/// Goto Definition
pub fn goto_definition(state: &ServerState, params: &GotoDefinitionParams) -> Option<GotoDefinitionResponse> {
    let uri = &params.text_document_position_params.text_document.uri;
    let pos = params.text_document_position_params.position;
    let doc = state.documents.get(uri)?;
    let line_text = get_line_text(&doc.content, pos.line);
    let trimmed = line_text.trim();

    // goto <label>
    if trimmed.to_lowercase().starts_with("goto ") {
        let target = trimmed.get(5..)?.trim();
        return find_label_location(doc, uri, target);
    }

    // callScript "path"
    if trimmed.to_lowercase().starts_with("callscript ") {
        let after = trimmed.get("callscript ".len()..)?;
        let path = extract_quoted_string(after)?;
        return resolve_script_file(state, uri, &path);
    }

    None
}

/// Find References
pub fn find_references(state: &ServerState, params: &ReferenceParams) -> Vec<Location> {
    let uri = &params.text_document_position.text_document.uri;
    let pos = params.text_document_position.position;
    let Some(doc) = state.documents.get(uri) else { return Vec::new() };
    let line_text = get_line_text(&doc.content, pos.line);
    let trimmed = line_text.trim();

    // 在标签定义行 (* label) 上 → 查找引用
    if let Some(rest) = trimmed.strip_prefix("* ") {
        let label_name = rest.trim();
        if !label_name.is_empty() {
            return find_label_references(doc, uri, label_name);
        }
    }

    Vec::new()
}

/// Document Symbols
pub fn document_symbols(state: &ServerState, uri: &Url) -> Vec<DocumentSymbol> {
    let Some(doc) = state.documents.get(uri) else { return Vec::new() };
    let Some(script) = &doc.script else { return Vec::new() };

    let mut symbols = Vec::new();
    for (idx, node) in script.nodes.iter().enumerate() {
        let line = script.get_source_line(idx).unwrap_or(1).saturating_sub(1) as u32;
        let range = Range::new(Position::new(line, 0), Position::new(line, 80));
        let selection_range = range;

        #[allow(clippy::single_match)]
        match node {
            ScriptNode::Chapter { title, .. } => {
                symbols.push(make_symbol(title.clone(), SymbolKind::NAMESPACE, range, selection_range, None));
            }
            ScriptNode::Label { name } => {
                symbols.push(make_symbol(name.clone(), SymbolKind::KEY, range, selection_range, Some("label".to_string())));
            }
            ScriptNode::Choice { options, .. } => {
                let text: Vec<&str> = options.iter().map(|o| o.text.as_str()).collect();
                let name = format!("choice: {}", text.join(" / "));
                symbols.push(make_symbol(name, SymbolKind::ENUM, range, selection_range, None));
            }
            _ => {}
        }
    }
    symbols
}

// --- 内部辅助函数 ---

fn find_label_location(doc: &DocumentState, uri: &Url, target: &str) -> Option<GotoDefinitionResponse> {
    let script = doc.script.as_ref()?;
    let idx = script.find_label(target)?;
    let line = script.get_source_line(idx)?.saturating_sub(1) as u32;
    Some(GotoDefinitionResponse::Scalar(Location {
        uri: uri.clone(),
        range: Range::new(Position::new(line, 0), Position::new(line, 0)),
    }))
}

fn resolve_script_file(state: &ServerState, current_uri: &Url, path: &str) -> Option<GotoDefinitionResponse> {
    let root = state.workspace_root.as_ref()?;
    // 脚本路径相对于当前文件目录
    let current_path = current_uri.to_file_path().ok()?;
    let dir = current_path.parent()?;
    let target_path = dir.join(path);
    let target_uri = Url::from_file_path(target_path).ok()?;
    Some(GotoDefinitionResponse::Scalar(Location {
        uri: target_uri,
        range: Range::new(Position::new(0, 0), Position::new(0, 0)),
    }))
}

fn find_label_references(doc: &DocumentState, uri: &Url, label_name: &str) -> Vec<Location> {
    let mut refs = Vec::new();
    for (line_idx, line) in doc.content.lines().enumerate() {
        let trimmed = line.trim();
        // goto label
        if trimmed.to_lowercase().starts_with("goto ") {
            if let Some(target) = trimmed.get(5..) {
                if target.trim() == label_name {
                    refs.push(make_location(uri, line_idx as u32));
                }
            }
        }
        // 表格中的标签引用
        if trimmed.starts_with('|') && trimmed.contains(label_name) {
            refs.push(make_location(uri, line_idx as u32));
        }
    }
    refs
}

fn make_location(uri: &Url, line: u32) -> Location {
    Location {
        uri: uri.clone(),
        range: Range::new(Position::new(line, 0), Position::new(line, 80)),
    }
}

fn make_symbol(name: String, kind: SymbolKind, range: Range, selection_range: Range, detail: Option<String>) -> DocumentSymbol {
    #[allow(deprecated)] // DocumentSymbol.deprecated field is deprecated but required
    DocumentSymbol {
        name,
        kind,
        range,
        selection_range,
        detail,
        children: None,
        tags: None,
        deprecated: None,
    }
}

fn get_line_text(content: &str, line: u32) -> &str {
    content.lines().nth(line as usize).unwrap_or("")
}

fn extract_quoted_string(s: &str) -> Option<String> {
    let start = s.find('"')?;
    let rest = s.get(start + 1..)?;
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}
```

### 3. 创建 `tools/ring-lsp/src/hover.rs`

```rust
use tower_lsp::lsp_types::*;
use crate::builtins::COMMANDS;
use crate::state::ServerState;

pub fn hover(state: &ServerState, params: &HoverParams) -> Option<Hover> {
    let uri = &params.text_document_position_params.text_document.uri;
    let pos = params.text_document_position_params.position;
    let doc = state.documents.get(uri)?;
    let line_text = get_line_text(&doc.content, pos.line);
    let word = get_word_at_position(line_text, pos.character as usize);

    // 指令名悬停
    if let Some(cmd) = COMMANDS.iter().find(|c| c.name.eq_ignore_ascii_case(word)) {
        return Some(Hover {
            contents: HoverContents::Markup(MarkupContent {
                kind: MarkupKind::Markdown,
                value: format!("**{}**\n\n```\n{}\n```\n\n{}", cmd.name, cmd.syntax, cmd.description),
            }),
            range: None,
        });
    }

    // goto 目标悬停
    let trimmed = line_text.trim();
    if trimmed.to_lowercase().starts_with("goto ") {
        if let Some(target) = trimmed.get(5..) {
            let target = target.trim();
            if let Some(script) = &doc.script {
                if let Some(idx) = script.find_label(target) {
                    let def_line = script.get_source_line(idx).unwrap_or(0);
                    return Some(Hover {
                        contents: HoverContents::Markup(MarkupContent {
                            kind: MarkupKind::Markdown,
                            value: format!("标签 `* {target}` 定义于第 {def_line} 行"),
                        }),
                        range: None,
                    });
                }
            }
        }
    }

    None
}

fn get_line_text(content: &str, line: u32) -> &str {
    content.lines().nth(line as usize).unwrap_or("")
}

fn get_word_at_position(line: &str, col: usize) -> &str {
    let col = col.min(line.len());
    let start = line[..col]
        .rfind(|c: char| c.is_whitespace() || c == '"' || c == '(' || c == ')')
        .map_or(0, |i| i + 1);
    let end = line[col..]
        .find(|c: char| c.is_whitespace() || c == '"' || c == '(' || c == ')')
        .map_or(line.len(), |i| i + col);
    line.get(start..end).unwrap_or("")
}
```

