1	//! # 资源索引
2	//!
3	//! 启动时扫描 workspace 的 `assets/` 目录，建立资源文件索引，
4	//! 按文件类型分类，供补全和资源存在性验证使用。
5	
6	use std::{collections::BTreeMap, path::Path};
7	
8	use walkdir::WalkDir;
9	
10	/// 资源文件类型
11	#[derive(Debug, Clone, PartialEq, Eq)]
12	pub(crate) enum AssetType {
13	    /// 图片（背景/立绘/场景）
14	    Image,
15	    /// 音频（BGM/SFX）
16	    Audio,
17	    /// 视频（cutscene）
18	    Video,
19	    /// 脚本文件（.rks）
20	    Script,
21	    /// 其他类型
22	    Other,
23	}
24	
25	/// 单条资源记录
26	#[derive(Debug, Clone)]
27	pub(crate) struct AssetEntry {
28	    /// 相对于 `assets/` 目录的路径，使用 `/` 分隔符
29	    pub(crate) relative_path: String,
30	    /// 资源类型
31	    pub(crate) asset_type: AssetType,
32	}
33	
34	/// 资源文件索引
35	///
36	/// 以 `BTreeMap` 保证遍历顺序稳定（补全列表按字典序排列）。
37	#[derive(Debug, Default)]
38	pub(crate) struct AssetIndex {
39	    entries: BTreeMap<String, AssetEntry>,
40	}
41	
42	impl AssetIndex {
43	    /// 扫描 `assets_dir` 目录，构建资源索引。
44	    ///
45	    /// 若目录不存在则返回空索引，不报错。
46	    pub(crate) fn scan(assets_dir: &Path) -> Self {
47	        let mut index = Self::default();
48	        if !assets_dir.exists() {
49	            return index;
50	        }
51	        for entry in WalkDir::new(assets_dir).into_iter().filter_map(Result::ok) {
52	            if !entry.file_type().is_file() {
53	                continue;
54	            }
55	            let rel_path = entry
56	                .path()
57	                .strip_prefix(assets_dir)
58	                .unwrap_or(entry.path())
59	                .to_string_lossy()
60	                .replace('\\', "/");
61	            let asset_type = classify_extension(entry.path());
62	            index.entries.insert(
63	                rel_path.clone(),
64	                AssetEntry {
65	                    relative_path: rel_path,
66	                    asset_type,
67	                },
68	            );
69	        }
70	        index
71	    }
72	
73	    /// 返回指定类型的所有资源条目（用于补全过滤）。
74	    pub(crate) fn completions_for_type(&self, filter_type: &AssetType) -> Vec<&AssetEntry> {
75	        self.entries
76	            .values()
77	            .filter(|e| &e.asset_type == filter_type)
78	            .collect()
79	    }
80	
81	    /// 返回全部资源条目的迭代器。
82	    #[expect(dead_code, reason = "后续功能（如悬停提示、资源浏览）将使用此接口")]
83	    pub(crate) fn all_entries(&self) -> impl Iterator<Item = &AssetEntry> {
84	        self.entries.values()
85	    }
86	
87	    /// 检查给定路径（相对于 `assets/`）是否存在于索引中。
88	    ///
89	    /// 路径分隔符会规范化为 `/` 后再查找。
90	    pub(crate) fn exists(&self, relative_path: &str) -> bool {
91	        let normalized = relative_path.replace('\\', "/");
92	        self.entries.contains_key(&normalized)
93	    }
94	}
95	
96	/// 根据文件扩展名判断资源类型（大小写不敏感）。
97	fn classify_extension(path: &Path) -> AssetType {
98	    match path
99	        .extension()
100	        .and_then(|e| e.to_str())
101	        .unwrap_or("")
102	        .to_lowercase()
103	        .as_str()
104	    {
105	        "png" | "jpg" | "jpeg" | "webp" | "bmp" => AssetType::Image,
