316	///
317	/// # 返回
318	///
319	/// 资源引用列表
320	pub fn extract_resource_references(script: &Script) -> Vec<ResourceReference> {
321	    let mut refs = Vec::new();
322	    extract_from_nodes(&script.nodes, script, &mut refs);
323	    refs
324	}
