326	/// 从节点列表提取资源引用
327	fn extract_from_nodes(nodes: &[ScriptNode], script: &Script, refs: &mut Vec<ResourceReference>) {
328	    for node in nodes {
329	        match node {
330	            ScriptNode::ChangeBG { path, .. } => {
331	                refs.push(ResourceReference {
332	                    resource_type: ResourceType::Background,
333	                    path: path.clone(),
334	                    resolved_path: script.resolve_path(path),
335	                });
