/// 验证文档中所有资源引用是否存在于 `AssetIndex` 中。
///
/// 解析成功后调用。对每个缺失的资源路径追加 Warning 级诊断。
/// `script_dir_from_assets` 是脚本文件所在目录相对于 `assets/` 的路径（如 `scripts/remake`）。
pub(crate) fn validate_resources(
    doc: &mut DocumentState,
    assets: &AssetIndex,
    script_dir_from_assets: Option<&str>,
) {
    let Some(script) = &doc.script else {
        return;
    };
    let refs = extract_resource_references(script);
    for r in &refs {
        if r.path.is_empty() {
            continue;
        }
        let resolved = resolve_asset_path(script_dir_from_assets, &r.path);
        if assets.exists(&resolved) {
            continue;
        }
        let line = find_resource_line(script, &r.path).unwrap_or(0);
        doc.diagnostics.push(Diagnostic {
            range: single_line_range(line),
            severity: Some(DiagnosticSeverity::WARNING),
            source: Some("ring-lsp".to_owned()),
            message: format!("资源不存在: {}", r.path),
            ..Default::default()
        });
    }
}

/// 将脚本中的相对资源路径解析为相对于 `assets/` 目录的规范路径。
///
/// 例如：脚本在 `assets/scripts/remake/main.rks`，
/// `script_dir_from_assets` = `"scripts/remake"`，
/// `raw_path` = `"../../backgrounds/black.png"`，
/// 返回 `"backgrounds/black.png"`。
fn resolve_asset_path(script_dir_from_assets: Option<&str>, raw_path: &str) -> String {
    let base = script_dir_from_assets.unwrap_or("");
    if base.is_empty() {
        return raw_path.replace('\\', "/");
    }
    let combined = format!("{}/{}", base, raw_path);
    normalize_path(&combined)
}

/// 规范化路径：折叠 `..` 和 `.` 组件，统一使用 `/` 分隔符。
fn normalize_path(path: &str) -> String {
    let path = path.replace('\\', "/");
    let mut parts: Vec<&str> = Vec::new();
    for component in path.split('/') {
        match component {
            "" | "." => {}
            ".." => {
                parts.pop();
            }
            other => parts.push(other),
        }
    }
    parts.join("/")
}

