use std::sync::Arc;

use tokio::sync::RwLock;
use tower_lsp::{
    Client, LanguageServer,
    jsonrpc::Result,
    lsp_types::{
        CompletionOptions, CompletionParams, CompletionResponse, DidChangeTextDocumentParams,
        DidCloseTextDocumentParams, DidOpenTextDocumentParams, DocumentSymbolParams,
        DocumentSymbolResponse, GotoDefinitionParams, GotoDefinitionResponse, Hover, HoverParams,
        HoverProviderCapability, InitializeParams, InitializeResult, Location, OneOf,
        ReferenceParams, ServerCapabilities, TextDocumentSyncCapability, TextDocumentSyncKind,
    },
};

use crate::{
    analysis::{analyze_document, validate_resources},
    assets::AssetIndex,
    state::{DocumentState, ServerState},
};

pub(crate) struct Backend {
    client: Client,
    state: Arc<RwLock<ServerState>>,
}

impl Backend {
    pub(crate) fn new(client: Client) -> Self {
        Self {
            client,
            state: Arc::new(RwLock::new(ServerState::new())),
        }
    }
}

#[tower_lsp::async_trait]
impl LanguageServer for Backend {
    async fn initialize(&self, params: InitializeParams) -> Result<InitializeResult> {
        // 从初始化参数中提取 workspace root
        let workspace_root = params
            .root_uri
            .as_ref()
            .and_then(|uri| uri.to_file_path().ok())
            .or_else(|| {
                params
                    .workspace_folders
                    .as_deref()
                    .and_then(|folders| folders.first())
                    .and_then(|f| f.uri.to_file_path().ok())
            });

        {
            let mut state = self.state.write().await;
            if let Some(ref root) = workspace_root {
                state.assets = AssetIndex::scan(&root.join("assets"));
            }
            state.workspace_root = workspace_root;
        }

        Ok(InitializeResult {
            capabilities: ServerCapabilities {
                text_document_sync: Some(TextDocumentSyncCapability::Kind(
                    TextDocumentSyncKind::FULL,
                )),
                completion_provider: Some(CompletionOptions {
                    trigger_characters: Some(vec![
                        "\"".to_string(),
                        " ".to_string(),
                        "$".to_string(),
                    ]),
                    ..Default::default()
                }),
                definition_provider: Some(OneOf::Left(true)),
                references_provider: Some(OneOf::Left(true)),
                document_symbol_provider: Some(OneOf::Left(true)),
                hover_provider: Some(HoverProviderCapability::Simple(true)),
                ..Default::default()
            },
            ..Default::default()
        })
    }

    async fn shutdown(&self) -> Result<()> {
        Ok(())
    }

    async fn did_open(&self, params: DidOpenTextDocumentParams) {
        let uri = params.text_document.uri.clone();
        let content = params.text_document.text;
        let version = params.text_document.version;

        let mut doc = DocumentState {
            content,
            version,
            script: None,
            diagnostics: Vec::new(),
        };
        analyze_document(&uri, &mut doc);
        {
            let state = self.state.read().await;
            validate_resources(&mut doc, &state.assets);
        }
        let diagnostics = doc.diagnostics.clone();

        {
            let mut state = self.state.write().await;
            state.documents.insert(uri.clone(), doc);
        }

        self.client
            .publish_diagnostics(uri, diagnostics, Some(version))
            .await;
    }

    async fn did_change(&self, params: DidChangeTextDocumentParams) {
        let uri = params.text_document.uri.clone();
        let version = params.text_document.version;

        // FULL 同步模式：取最后一个变更内容即为完整文档
        let content = params
            .content_changes
            .into_iter()
            .last()
            .map(|c| c.text)
            .unwrap_or_default();

        let mut doc = DocumentState {
            content,
            version,
            script: None,
            diagnostics: Vec::new(),
        };
        analyze_document(&uri, &mut doc);
        {
            let state = self.state.read().await;
            validate_resources(&mut doc, &state.assets);
        }
        let diagnostics = doc.diagnostics.clone();

        {
            let mut state = self.state.write().await;
            state.documents.insert(uri.clone(), doc);
        }

        self.client
            .publish_diagnostics(uri, diagnostics, Some(version))
            .await;
    }

    async fn did_close(&self, params: DidCloseTextDocumentParams) {
        let uri = params.text_document.uri.clone();

        {
            let mut state = self.state.write().await;
            state.documents.remove(&uri);
        }

        // 关闭文档后清空诊断
        self.client.publish_diagnostics(uri, Vec::new(), None).await;
    }

    async fn completion(&self, params: CompletionParams) -> Result<Option<CompletionResponse>> {
        let state = self.state.read().await;
        let items = crate::completion::complete(&state, &params);
        Ok(Some(CompletionResponse::Array(items)))
    }

    async fn goto_definition(
        &self,
        params: GotoDefinitionParams,
    ) -> Result<Option<GotoDefinitionResponse>> {
        let state = self.state.read().await;
        Ok(crate::navigation::goto_definition(&state, &params))
    }

    async fn references(&self, params: ReferenceParams) -> Result<Option<Vec<Location>>> {
        let state = self.state.read().await;
        let refs = crate::navigation::find_references(&state, &params);
        Ok(if refs.is_empty() { None } else { Some(refs) })
    }

    async fn document_symbol(
        &self,
        params: DocumentSymbolParams,
    ) -> Result<Option<DocumentSymbolResponse>> {
        let state = self.state.read().await;
        let symbols = crate::navigation::document_symbols(&state, &params.text_document.uri);
        Ok(Some(DocumentSymbolResponse::Nested(symbols)))
    }

    async fn hover(&self, params: HoverParams) -> Result<Option<Hover>> {
        let state = self.state.read().await;
        Ok(crate::hover::hover(&state, &params))
    }
}

