//! # 诊断分析
//!
//! 将 vn-runtime 的解析和诊断结果转换为 LSP `Diagnostic` 格式，
//! 并存储到 `DocumentState` 中。

use tower_lsp::lsp_types::{Diagnostic, DiagnosticSeverity, Position, Range, Url};
use vn_runtime::{
    diagnostic::{DiagnosticLevel, analyze_script, extract_resource_references},
    error::ParseError,
    script::{ast::Script, parser::Parser},
};

use crate::{assets::AssetIndex, state::DocumentState};

/// 分析文档内容，将解析和语义诊断写入 `DocumentState`。
///
/// `base_path` 为脚本文件所在目录相对于 `assets/` 的路径（如 `scripts/remake`），
/// 用于正确解析资源相对路径。
pub(crate) fn analyze_document(uri: &Url, doc: &mut DocumentState, base_path: &str) {
    let script_id = uri.as_str();
    let mut parser = Parser::new();

    match parser.parse_with_base_path(script_id, &doc.content, base_path) {
        Ok(script) => {
            // 解析成功：进行语义分析
            let result = analyze_script(&script);
            doc.script = Some(script);
            doc.diagnostics = result.diagnostics.iter().map(vn_diag_to_lsp).collect();
        }
        Err(parse_err) => {
            // 解析失败：将 ParseError 转换为 LSP 诊断
            doc.script = None;
            doc.diagnostics = vec![parse_error_to_lsp(&parse_err)];
        }
    }
}

/// 将 vn-runtime `Diagnostic` 转换为 LSP `Diagnostic`。
///
/// vn-runtime 行号从 1 开始，LSP 行号从 0 开始，转换时用 `saturating_sub(1)`。
fn vn_diag_to_lsp(diag: &vn_runtime::diagnostic::Diagnostic) -> Diagnostic {
    let line = diag.line.unwrap_or(1).saturating_sub(1) as u32;
    let range = single_line_range(line);

    let severity = match diag.level {
        DiagnosticLevel::Error => DiagnosticSeverity::ERROR,
        DiagnosticLevel::Warn => DiagnosticSeverity::WARNING,
        DiagnosticLevel::Info => DiagnosticSeverity::INFORMATION,
    };

    let message = if let Some(detail) = &diag.detail {
        format!("{}\n{}", diag.message, detail)
    } else {
        diag.message.clone()
    };

    Diagnostic {
        range,
        severity: Some(severity),
        source: Some("ring-lsp".to_owned()),
        message,
        ..Default::default()
    }
}

/// 将 `ParseError` 转换为 LSP `Diagnostic`。
///
/// vn-runtime 行号从 1 开始，LSP 行号从 0 开始，转换时用 `saturating_sub(1)`。
fn parse_error_to_lsp(err: &ParseError) -> Diagnostic {
    let (line_1based, message) = match err {
        ParseError::InvalidLine { line, message } => (*line, format!("无效的格式：{message}")),
        ParseError::UnknownCommand { line, command } => (*line, format!("未知指令：{command}")),
        ParseError::MissingParameter {
            line,
            command,
            param,
        } => (*line, format!("指令 '{command}' 缺少参数 '{param}'")),
        ParseError::InvalidParameter {
            line,
            param,
            message,
        } => (*line, format!("参数 '{param}' 无效：{message}")),
        ParseError::InvalidTable { line, message } => (*line, format!("无效的表格格式：{message}")),
        ParseError::InvalidTransition { line, message } => {
            (*line, format!("无效的过渡效果语法：{message}"))
        }
    };

    let line = line_1based.saturating_sub(1) as u32;
    Diagnostic {
        range: single_line_range(line),
        severity: Some(DiagnosticSeverity::ERROR),
        source: Some("ring-lsp".to_owned()),
        message,
        ..Default::default()
    }
}

/// 构造指向某行行首的零长度 Range（列 0..0）。
fn single_line_range(line: u32) -> Range {
    Range {
        start: Position { line, character: 0 },
        end: Position { line, character: 0 },
    }
}

/// 验证文档中所有资源引用是否存在于 `AssetIndex` 中。
///
/// 使用 `ResourceReference::resolved_path`（由 parser 的 `base_path` 解析），
/// 规范化后查索引。
pub(crate) fn validate_resources(doc: &mut DocumentState, assets: &AssetIndex) {
    let Some(script) = &doc.script else {
        return;
    };
    let refs = extract_resource_references(script);
    for r in &refs {
        if r.path.is_empty() {
            continue;
        }
        let normalized = normalize_path(&r.resolved_path);
        if assets.exists(&normalized) {
            continue;
        }
        let line = find_resource_line(script, &r.path).unwrap_or(0);
        doc.diagnostics.push(Diagnostic {
            range: single_line_range(line),
            severity: Some(DiagnosticSeverity::WARNING),
            source: Some("ring-lsp".to_owned()),
            message: format!("资源不存在: {}", r.path),
            ..Default::default()
        });
    }
}

/// 规范化路径：折叠 `..` 和 `.` 组件，统一使用 `/` 分隔符。
fn normalize_path(path: &str) -> String {
    let path = path.replace('\\', "/");
    let mut parts: Vec<&str> = Vec::new();
    for component in path.split('/') {
        match component {
            "" | "." => {}
            ".." => {
                parts.pop();
            }
            other => parts.push(other),
        }
    }
    parts.join("/")
}

#[cfg(test)]
mod tests {
    use tower_lsp::lsp_types::Url;

    use super::*;
    use crate::state::DocumentState;

    fn make_doc(content: &str) -> DocumentState {
        DocumentState {
            content: content.to_string(),
            version: 1,
            script: None,
            diagnostics: Vec::new(),
        }
    }

    #[test]
    fn test_valid_script_no_errors() {
        let uri = Url::parse("file:///test.rks").unwrap();
        let mut doc = make_doc("# Chapter\n角色：\"台词\"");
        analyze_document(&uri, &mut doc);
        assert!(doc.script.is_some(), "有效脚本应成功解析");
        assert!(doc.diagnostics.is_empty(), "有效脚本不应产生诊断");
    }

    #[test]
    fn test_parse_error_produces_diagnostic() {
        let uri = Url::parse("file:///test.rks").unwrap();
        // changeBG 缺少必要的图片路径参数，应产生 MissingParameter 错误
        let mut doc = make_doc("changeBG");
        analyze_document(&uri, &mut doc);
        assert!(!doc.diagnostics.is_empty(), "解析错误应转换为诊断");
        assert_eq!(
            doc.diagnostics[0].severity,
            Some(tower_lsp::lsp_types::DiagnosticSeverity::ERROR),
            "解析错误应为 ERROR 级别"
        );
    }

    #[test]
    fn test_undefined_label_diagnostic() {
        let uri = Url::parse("file:///test.rks").unwrap();
        // goto 引用了一个不存在的标签，语义分析应产生诊断
        let mut doc = make_doc("* start\ngoto nonexistent_label");
        analyze_document(&uri, &mut doc);
        let has_undefined_diag = doc
            .diagnostics
            .iter()
            .any(|d| d.message.contains("nonexistent_label") || d.message.contains("未定义"));
        assert!(
            has_undefined_diag,
            "goto 引用不存在的标签应产生包含标签名或'未定义'的诊断"
        );
    }

    #[test]
    fn test_parse_error_clears_script() {
        let uri = Url::parse("file:///test.rks").unwrap();
        let mut doc = make_doc("goto");
        analyze_document(&uri, &mut doc);
        // 解析失败时 script 字段应为 None
        assert!(doc.script.is_none(), "解析失败时 script 应为 None");
    }
}

/// 在脚本的 `source_map` 中查找引用了指定资源路径的节点所在行（0-indexed，供 LSP 使用）。
///
/// 遍历节点，找到第一个资源路径匹配的节点，返回其 LSP 行号（vn-runtime 行号从 1 开始，
/// 转换为 0-indexed）。未找到时返回 `None`。
fn find_resource_line(script: &Script, path: &str) -> Option<u32> {
    use vn_runtime::script::ast::ScriptNode;

    for (index, node) in script.nodes.iter().enumerate() {
        let matched = match node {
            ScriptNode::ChangeBG { path: p, .. }
            | ScriptNode::ChangeScene { path: p, .. }
            | ScriptNode::PlayAudio { path: p, .. }
            | ScriptNode::ShowCharacter { path: Some(p), .. }
            | ScriptNode::Cutscene { path: p } => p == path,
            _ => false,
        };
        if matched {
            // get_source_line 返回从 1 开始的行号，LSP 需要 0-indexed
            let line_1based = script.get_source_line(index).unwrap_or(1);
            return Some(line_1based.saturating_sub(1) as u32);
        }
    }
    None
}

